import React, { useState } from 'react';
import { GoogleGenAI } from '@google/genai';
import { User, Sparkles, Loader2, FileText, Activity, AlertCircle, Pill, Stethoscope, CheckCircle } from 'lucide-react';
import { Patient } from '../../types';
import { AIAssistant } from '../../components/AIAssistant';
import { mockPatients } from '../../data/mockPatients';

const BodyProntuario: React.FC = () => {
  const [fileContent, setFileContent] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [extractedData, setExtractedData] = useState<Patient | null>(null);

  const [selectedPatientId] = useState(mockPatients[0].id);
  const basePatient = mockPatients.find(p => p.id === selectedPatientId) || mockPatients[0];

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setFileContent(event.target?.result as string);
      };
      reader.readAsText(file);
    }
  };

  const handleInterpret = async () => {
    if (!fileContent) {
      alert('Por favor, insira um prontuário (texto) ou faça upload de um arquivo primeiro.');
      return;
    }

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.REACT_APP_GEMINI_API_KEY || '' });
      const prompt = `
        Analise o seguinte texto médico e extraia as informações estruturadas.
        ${extractedData ? `ATENÇÃO: Este paciente já possui dados extraídos. Você deve MESCLAR as novas informações com os dados existentes abaixo. Não perca nenhuma informação anterior, apenas adicione ou atualize.\nDados Atuais: ${JSON.stringify(extractedData)}\n\nNovas informações a serem adicionadas:\n` : 'Prontuário para análise:\n'}
        ${fileContent}

        Retorne APENAS um objeto JSON válido, sem nenhuma marcação markdown (como \`\`\`json), com a exata estrutura abaixo. Se uma informação não for encontrada, use um array vazio [] ou string vazia "".

        {
          "id": "P-10042",
          "name": "Nome do paciente extraído",
          "age": 30,
          "gender": "Feminino",
          "bloodType": "O+",
          "allergies": ["Alergia 1"],
          "conditions": ["Condição 1"],
          "medications": ["Medicação 1"],
          "labResults": [
            { "id": "L1", "test": "Nome do Exame", "result": "Valor", "unit": "Unidade", "referenceRange": "Ref", "date": "2023-10-18", "status": "normal" }
          ],
          "recentVisits": [
            { "id": "V1", "date": "2023-10-15", "doctor": "Nome do Médico", "reason": "Motivo da consulta", "notes": "Resumo da consulta" }
          ],
          "notes": "Notas clínicas gerais extraídas"
        }

        Prontuário para análise:
        ${fileContent}
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-1.5-pro',
        contents: prompt,
      });

      const text = response.text || '';
      const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsedData = JSON.parse(jsonStr) as Patient;

      setExtractedData({
        ...basePatient,
        ...parsedData,
        id: parsedData.id || basePatient.id,
      });
      setFileContent('');
    } catch (error) {
      console.error('Erro ao fazer parse do JSON:', error);
      alert('Erro ao interpretar o prontuário. Por favor, tente novamente com um texto mais claro.');
    } finally {
      setIsAnalyzing(false);
    }
  };

  const activePatient = extractedData || basePatient;

  return (
    <div className="flex flex-1 overflow-hidden">
      {/* Left Sidebar - Patient Info */}
      <div className="w-72 bg-[#1E3A8A] p-6 text-white flex flex-col overflow-y-auto flex-shrink-0">
        <p className="mb-6 text-sm font-medium text-blue-200">Data: 10/10/2026 Horário: 10:20h</p>

        <div className="mb-6 flex justify-center">
          <div className="flex h-28 w-28 items-center justify-center rounded-full border-4 border-[#F5A623] bg-white text-gray-800 overflow-hidden shadow-lg">
            <User className="h-16 w-16" />
          </div>
        </div>

        <div className="space-y-3 text-sm">
          <p><span className="font-bold text-[#F5A623]">Paciente:</span> {activePatient.name}</p>
          <p><span className="font-bold text-[#F5A623]">Idade:</span> {activePatient.age} anos</p>
          <p><span className="font-bold text-[#F5A623]">Sexo:</span> {activePatient.gender}</p>
          <p><span className="font-bold text-[#F5A623]">CPF:</span> 333.333.333-33</p>
          <p><span className="font-bold text-[#F5A623]">Endereço:</span> Rua das Flores, 513<br />Centro - São Paulo</p>
          <p><span className="font-bold text-[#F5A623]">Telefone:</span> (11) 970154684</p>
          <p><span className="font-bold text-[#F5A623]">Histórico Médico:</span> {activePatient.conditions.join(', ')}</p>
        </div>
      </div>

      {/* Middle Content Area */}
      <div className="flex-1 overflow-y-auto bg-gray-100 p-6">
        <div className="mx-auto max-w-4xl">
          {/* Action Buttons */}
          <div className="mb-6 flex flex-wrap items-center gap-4">
            <button className="flex items-center justify-between rounded-md bg-[#2E5B9F] px-4 py-2.5 font-bold text-white shadow-sm hover:bg-blue-800 transition-colors">
              <span className="text-sm">CONSULTAR PRONTUÁRIOS ANTIGOS</span>
              <div className="ml-3 text-lg text-[#F5A623] font-black">++</div>
            </button>

            <button
              onClick={handleInterpret}
              disabled={isAnalyzing || !fileContent}
              className="flex items-center justify-between rounded-md bg-[#2E5B9F] px-4 py-2.5 font-bold text-white shadow-sm hover:bg-blue-800 transition-colors disabled:opacity-70"
            >
              <div className="flex items-center text-sm">
                {isAnalyzing && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                <span>{extractedData ? 'ADICIONAR AO PRONTUÁRIO' : 'INTERPRETAR PRONTUÁRIO'}</span>
              </div>
              <div className="ml-3 text-lg text-[#F5A623] font-black">++</div>
            </button>

            <div className="flex-1"></div>

            {extractedData && (
              <button
                onClick={() => {
                  alert('Exame fechado e salvo com sucesso!');
                  window.location.href = '/medico';
                }}
                className="flex items-center rounded-md bg-emerald-600 px-4 py-2.5 text-sm font-bold text-white shadow-sm hover:bg-emerald-700 transition-colors"
              >
                <CheckCircle className="mr-2 h-4 w-4" />
                FECHAR EXAME
              </button>
            )}

            <button className="flex items-center rounded-md bg-[#F5A623] px-4 py-2.5 text-sm font-bold text-white shadow-sm hover:bg-orange-500 transition-colors">
              <Sparkles className="mr-2 h-4 w-4" />
              Gerar Resumo Inteligente
            </button>
          </div>

          {/* Input Area */}
          {!isAnalyzing && (
            <div className="rounded-xl bg-white p-6 shadow-sm border border-gray-200 mb-6">
              <h2 className="text-lg font-bold text-[#2E5B9F] mb-4">
                {extractedData ? 'Adicionar Mais Informações (Evolução, Novos Exames)' : 'Inserir Prontuário para Análise'}
              </h2>
              <div className="mb-4 flex items-center gap-4">
                <label className="inline-block cursor-pointer rounded-md bg-[#F5A623] px-4 py-2 text-sm font-bold text-white shadow-sm hover:bg-orange-500 transition-colors">
                  Escolher Arquivo
                  <input
                    type="file"
                    accept=".txt,.md,.csv"
                    onChange={handleFileUpload}
                    className="hidden"
                  />
                </label>
                <span className="text-sm text-gray-500">
                  {fileContent ? 'Arquivo carregado com sucesso!' : 'Nenhum arquivo escolhido'}
                </span>
              </div>
              <textarea
                value={fileContent}
                onChange={(e) => setFileContent(e.target.value)}
                className={`w-full p-3 border border-gray-300 rounded-md focus:ring-[#4A86E8] focus:border-[#4A86E8] text-sm ${extractedData ? 'h-24' : 'h-48'}`}
                placeholder={extractedData ? 'Cole novas anotações, resultados de exames ou evolução clínica aqui...' : 'Cole o texto do prontuário aqui para que a IA possa extrair as informações estruturadas...'}
              />
            </div>
          )}

          {/* Loading State */}
          {isAnalyzing && (
            <div className="flex flex-col items-center justify-center rounded-xl bg-blue-50 p-6 shadow-sm border border-blue-100 mb-6">
              <Loader2 className="h-8 w-8 animate-spin text-[#F5A623] mb-3" />
              <p className="text-md font-bold text-[#2E5B9F]">Processando informações...</p>
              <p className="text-xs text-gray-500 mt-1">A IA está extraindo e atualizando o quadro clínico.</p>
            </div>
          )}

          {/* Extracted Data Grid */}
          {extractedData && (
            <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
              {/* Left Column */}
              <div className="space-y-6">
                {/* Basic Info */}
                <div className="rounded-xl bg-white p-5 shadow-sm border border-gray-200">
                  <div className="flex items-center gap-3 mb-4">
                    <div className="flex h-10 w-10 items-center justify-center rounded-full bg-blue-50 text-[#2E5B9F]">
                      <User className="h-5 w-5" />
                    </div>
                    <div>
                      <h2 className="text-lg font-bold text-gray-900">{extractedData.name}</h2>
                      <p className="text-xs text-gray-500">{extractedData.age} anos, {extractedData.gender}</p>
                    </div>
                  </div>
                  <div className="text-sm text-gray-600 space-y-1">
                    <p><span className="font-medium">ID:</span> {extractedData.id}</p>
                    <p><span className="font-medium">Tipo Sanguíneo:</span> {extractedData.bloodType}</p>
                  </div>
                </div>

                {/* Condições e Alergias */}
                <div className="rounded-xl bg-white p-5 shadow-sm border border-gray-200">
                  <h3 className="mb-4 flex items-center text-md font-bold text-gray-900">
                    <AlertCircle className="mr-2 h-5 w-5 text-[#F5A623]" />
                    Condições e Alergias
                  </h3>
                  <div className="space-y-4">
                    <div>
                      <h4 className="mb-2 text-xs font-semibold uppercase tracking-wider text-gray-500">Condições Crônicas</h4>
                      {extractedData.conditions.length > 0 ? (
                        <ul className="list-inside list-disc space-y-1 text-sm text-gray-700">
                          {extractedData.conditions.map((c, i) => <li key={i}>{c}</li>)}
                        </ul>
                      ) : (
                        <p className="text-sm text-gray-500">Nenhuma condição registrada.</p>
                      )}
                    </div>
                    <div>
                      <h4 className="mb-2 text-xs font-semibold uppercase tracking-wider text-gray-500">Alergias</h4>
                      {extractedData.allergies.length > 0 ? (
                        <div className="flex flex-wrap gap-2">
                          {extractedData.allergies.map((a, i) => (
                            <span key={i} className="inline-flex items-center rounded-full bg-red-50 px-2.5 py-0.5 text-xs font-medium text-red-700 border border-red-100">
                              {a}
                            </span>
                          ))}
                        </div>
                      ) : (
                        <p className="text-sm text-gray-500">Nenhuma alergia registrada.</p>
                      )}
                    </div>
                  </div>
                </div>

                {/* Medicamentos */}
                <div className="rounded-xl bg-white p-5 shadow-sm border border-gray-200">
                  <h3 className="mb-4 flex items-center text-md font-bold text-gray-900">
                    <Pill className="mr-2 h-5 w-5 text-[#4A86E8]" />
                    Medicamentos em Uso
                  </h3>
                  {extractedData.medications.length > 0 ? (
                    <ul className="space-y-2">
                      {extractedData.medications.map((m, i) => (
                        <li key={i} className="flex items-start text-sm text-gray-700">
                          <span className="mr-2 mt-1.5 h-1.5 w-1.5 flex-shrink-0 rounded-full bg-[#4A86E8]" />
                          {m}
                        </li>
                      ))}
                    </ul>
                  ) : (
                    <p className="text-sm text-gray-500">Nenhum medicamento registrado.</p>
                  )}
                </div>
              </div>

              {/* Right Column */}
              <div className="space-y-6">
                {/* Resultados Laboratoriais */}
                <div className="rounded-xl bg-white p-5 shadow-sm border border-gray-200">
                  <h3 className="mb-4 flex items-center text-md font-bold text-gray-900">
                    <Activity className="mr-2 h-5 w-5 text-emerald-500" />
                    Resultados Laboratoriais Recentes
                  </h3>
                  <div className="space-y-3">
                    {extractedData.labResults.length > 0 ? (
                      extractedData.labResults.map((result, i) => (
                        <div key={i} className="flex items-center justify-between rounded-lg border border-gray-100 bg-gray-50 p-3">
                          <div>
                            <p className="font-medium text-gray-900 text-sm">{result.test}</p>
                            <p className="text-xs text-gray-500">{result.date}</p>
                          </div>
                          <div className="text-right">
                            <p className={`font-bold text-sm ${result.status !== 'normal' ? 'text-red-600' : 'text-emerald-600'}`}>
                              {result.result} {result.unit}
                            </p>
                            <p className="text-[10px] text-gray-500">Ref: {result.referenceRange}</p>
                          </div>
                        </div>
                      ))
                    ) : (
                      <p className="text-sm text-gray-500">Nenhum exame recente.</p>
                    )}
                  </div>
                </div>

                {/* Histórico de Consultas */}
                <div className="rounded-xl bg-white p-5 shadow-sm border border-gray-200">
                  <h3 className="mb-4 flex items-center text-md font-bold text-gray-900">
                    <Stethoscope className="mr-2 h-5 w-5 text-purple-500" />
                    Histórico de Consultas
                  </h3>
                  <div className="space-y-4">
                    {extractedData.recentVisits.length > 0 ? (
                      extractedData.recentVisits.map((visit, i) => (
                        <div key={i} className="rounded-lg border border-gray-100 bg-gray-50 p-3 shadow-sm">
                          <div className="flex items-center justify-between mb-1">
                            <h4 className="font-bold text-gray-900 text-sm">{visit.reason}</h4>
                            <time className="text-xs text-gray-500">{visit.date}</time>
                          </div>
                          <p className="text-xs font-medium text-purple-600 mb-2">{visit.doctor}</p>
                          <p className="text-xs text-gray-600 leading-relaxed">{visit.notes}</p>
                        </div>
                      ))
                    ) : (
                      <p className="text-sm text-gray-500">Nenhum histórico encontrado.</p>
                    )}
                  </div>
                </div>
              </div>

              {/* Full Width Notes */}
              <div className="lg:col-span-2 rounded-xl bg-[#FFF9EB] p-5 shadow-sm border border-[#F5A623]/20">
                <h3 className="mb-3 flex items-center text-md font-bold text-[#2E5B9F]">
                  <FileText className="mr-2 h-5 w-5 text-[#F5A623]" />
                  Notas Clínicas Gerais
                </h3>
                <p className="text-sm text-gray-700 leading-relaxed">
                  {extractedData.notes || 'Nenhuma nota adicional registrada.'}
                </p>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Right Sidebar - AI Assistant */}
      <div className="w-[400px] flex-shrink-0 border-l border-gray-200 bg-white">
        <AIAssistant patient={activePatient} />
      </div>
    </div>
  );
};

export default BodyProntuario;
